                    { id_orationis: 'o12', textus_originalis: "His rebus fiebat ut et minus late uagarentur et minus facile finitimis bellum inferre possent; qua ex parte homines bellandi cupidi magno dolore adficiebantur.", analysis_syntacticus: { /*...*/ }, translationes_explicatae: { /*...*/ }, verba: [ /*...*/ ] },
                    { id_orationis: 'o13', textus_originalis: "Pro multitudine autem hominum et pro gloria belli atque fortitudinis angustos se fines habere arbitrabantur, qui in longitudinem milia passuum CCXL, in latitudinem CLXXX patebant.", analysis_syntacticus: { /*...*/ }, translationes_explicatae: { /*...*/ }, verba: [ /*...*/ ] }
