                    // --- CAPÍTULO 4 ---
                    { id_orationis: 'o14', textus_originalis: "His rebus adducti et auctoritate Orgetorigis permoti constituerunt ea quae ad proficiscendum pertinerent comparare, iumentorum et carrorum quam maximum numerum coemere, sementes quam maximas facere, ut in itinere copia frumenti suppeteret, cum proximis ciuitatibus pacem et amicitiam confirmare.", analysis_syntacticus: { /*...*/ }, translationes_explicatae: { /*...*/ }, verba: [ /*...*/ ] },
                    { id_orationis: 'o15', textus_originalis: "Ad eas res conficiendas biennium sibi satis esse duxerunt; in tertium annum profectionem lege confirmant.", analysis_syntacticus: { /*...*/ }, translationes_explicatae: { /*...*/ }, verba: [ /*...*/ ] },
                    { id_orationis: 'o16', textus_originalis: "Ad eas res conficiendas Orgetorix deligitur.", analysis_syntacticus: { /*...*/ }, translationes_explicatae: { /*...*/ }, verba: [ /*...*/ ] },
                    { id_orationis: 'o17', textus_originalis: "Is sibi legationem ad ciuitates suscepit.", analysis_syntacticus: { /*...*/ }, translationes_explicatae: { /*...*/ }, verba: [ /*...*/ ] },
                    { id_orationis: 'o18', textus_originalis: "In eo itinere persuadet Castico, Catamantaloedis filio, Sequano, cuius pater regnum in Sequanis multos annos obtinuerat et a senatu populi Romani amicus appellatus erat, ut regnum in ciuitate sua occuparet quod pater ante habuerat; itemque Dumnorigi Haeduo, fratri Diuiciaci, qui eo tempore principatum in ciuitate optinebat ac maxime plebi acceptus erat, ut idem conaretur persuadet eique filiam suam in matrimonium dat.", analysis_syntacticus: { /*...*/ }, translationes_explicatae: { /*...*/ }, verba: [ /*...*/ ] },
                    { id_orationis: 'o19', textus_originalis: "Perfacile factu esse illis probat conata perficere, propterea quod ipse suae ciuitatis imperium obtenturus esset: non esse dubium quin totius Galliae plurimum Heluetii possent; se suis copiis suoque exercitu illis regna conciliaturum confirmat.", analysis_syntacticus: { /*...*/ }, translationes_explicatae: { /*...*/ }, verba: [ /*...*/ ] },
                    { id_orationis: 'o20', textus_originalis: "Hac oratione adducti inter se fidem et ius iurandum dant et regno occupato per tres potentissimos ac firmissimos populos totius Galliae sese potiri posse sperant.", analysis_syntacticus: { /*...*/ }, translationes_explicatae: { /*...*/ }, verba: [ /*...*/ ] }
